type Inner<T> = {value: T};
type Outer<T> = {inner: Inner<T>};
declare function unpack<T>(x: {[K in keyof T]: Outer<T[K]>}): T;
export const result = unpack([{inner: {value: "Ada"}}, {inner: {value: 3}}]);

function identity<T>(x: {[K in keyof T]: T[K]}): T { return x as T; }
export const result = identity(["Ada", 3]);
export const runtime = result[0] === "Ada" && result[1] === 3 ? 2 : 0;

function unpack<T extends unknown[]>(x: {[K in keyof T]: {value: T[K]}}): T { return [x[0].value, x[1].value] as unknown as T; }
export const result = unpack([{value: "Ada"}, {value: 3}]);
export const runtime = result[0] === "Ada" && result[1] === 3 ? 2 : 0;
